from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from rest_framework.exceptions import PermissionDenied
from langchain_core.tools import tool
from .models import WireTransfer

def get_user_wire_transfer_details(transfer_id: str, user) -> dict:
    """Retrieve wire transfer details scoped to the requesting user's account."""
    try:
        transfer = WireTransfer.objects.get(
            reference_code=transfer_id,
            account__user=user
        )
    except WireTransfer.DoesNotExist:
        raise PermissionDenied("Wire transfer not found or unauthorized")

    return {
        "reference": transfer.reference_code,
        "amount": str(transfer.amount),
        "currency": transfer.currency,
        "beneficiary_iban": transfer.beneficiary_iban,
        "beneficiary_name": transfer.beneficiary_name,
        "status": transfer.status,
    }

class AgentToolExecutionView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        tool_name = request.data.get("tool_name")
        tool_args = request.data.get("tool_args", {})

        if tool_name == "get_wire_transfer_details":
            transfer_id = tool_args.get("transfer_id")
            result = get_user_wire_transfer_details(transfer_id, request.user)
            return Response({"tool": tool_name, "output": result})

        return Response({"error": "Unknown tool"}, status=status.HTTP_400_BAD_REQUEST)
